 "content": "def transform(grid):
    # Cells are grouped into 3x3 blocks separated by the color-3 grid lines.
    # Mark a block containing two or more color-5 cells with color 1.
    h, w = len(grid), len(grid[0])
    row_starts = [i for i in range(h) if grid[i][0] != 3]
    col_starts = [j for j in range(w) if grid[0][j] != 3]
    out = []
    for r in row_starts:
        row = []
        for c in col_starts:
            count = sum(grid[i][j] == 5
                        for i in range(r, min(r + 3, h))
                        for j in range(c, min(c + 3, w)))
            row.append(1 if count >= 2 else 3)
        out.append(row)
    return out
