 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [i for i, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1]
    def bands(n, separators):
        result, start = [], 0
        for x in separators:
            if start < x:
                result.append((start, x))
            start = x + 1
        if start < n:
            result.append((start, n))
        return result
    rb, cb = bands(h, sep_rows), bands(w, sep_cols)
    result = []
    for r0,r1 in rb:
        outrow=[]
        for c0,c1 in cb:
            cells=[grid[i][j] for i in range(r0,r1) for j in range(c0,c1)]
            counts={x:cells.count(x) for x in set(cells)}
            background=max(counts, key=counts.get)
            other_count=len(cells)-counts[background]
            outrow.append(1 if other_count >= 2 else background)
        result.append(outrow)
    return result
